-- The global discriminators of the Geometry Variant are persisted in data, so they must never
-- change. New geo types are only appended. The blobs below were produced by a server without the
-- MultiPoint type (version 26.7.1.767, before the seventh variant was added) and must stay
-- readable forever. Do not regenerate them with a current server.

SELECT id, g, variantType(g) FROM format(Native, 'id Int32, g Geometry', unhex('')) ORDER BY id;

SELECT id, g, variantType(g) FROM format(RowBinary, 'id Int32, g Geometry', unhex('')) ORDER BY id;
